#!/usr/bin/env python3
"""
Round 154k (culprits), 3 October 2026. Needs round 154b.

Adds the Pen and ink basemap.

Run from the repository root (the apply-patch workflow does).
"""
import base64, pathlib, subprocess, sys, tempfile

NOTES = ['## Round 154k (3 October)\n\nNeeds round 154b. No tiles patch. No app.js?v= bump. One new basemap, Pen and ink.\nMade in a separate chat (letter "k") so it does not clash with the "b" rounds.\n\n- Asked 3 October: a basemap in the look of the Earth First! artwork in Cal\n  Poly Humboldt\'s Special Collections and a photocopied sabotage zine. Only the\n  way they are drawn is taken (black pen on pale paper, hatching, stipple,\n  ruled woodcut lines, photocopy grain); nothing from any picture is copied.\n- Drawn square by square on the reader\'s computer from the AWS heights\n  (inkdraw://, inkDrawSquare, about 0.2 s a square): the sea ruled across,\n  hairlines over the shelves and heavier in the deeps, a paper margin and one\n  firm line on every shore; land paper, slopes away from a north-west light\n  hatched, cross-hatched where darker, stippled in the half-light; far out,\n  high ground shaded by height; height lines from zoom 4. Seamless; the\n  world\'s top and bottom rows left paper so the globe\'s poles are clean.\n- Close in (OpenFreeMap): the sea ruled from zoom 7, forests as small pen\n  conifers, wetlands as reed tufts, towns stippled, lakes ruled and inked,\n  ice white, buildings hatched, main roads double-lined, railways with ties,\n  borders dash-dot (patterns drawn as pixels, inkPattern). Names black/grey.\n- Black ink and paper only (tested). Layers outline-ink-* (INK_IDS), one\n  block ("Pen and ink, a seventh basemap" to "end of Pen and ink") after\n  Woodlands; menu and switch by wrapping basemapPanelHtml and setBasemap;\n  listed last in the menu. Layer colours "suited to the basemap": deep.\n- Checked in Chromium with sample heights (zooms 0-2); not seen against the\n  live height tiles.\n']


def git(*a, check=True):
    return subprocess.run(["git", *a], capture_output=True, text=True, check=check)


def main():
    root = pathlib.Path(".")
    if not (root / "map" / "app.js").exists():
        sys.exit("round154k: run from the culprits repository root")
    h = root / "HANDOFF.md"
    if "## Round 154b" not in h.read_text(encoding="utf-8"):
        sys.exit("round154k: round 154b must be applied first")
    with tempfile.NamedTemporaryFile("wb", suffix=".diff", delete=False) as f:
        f.write(base64.b64decode(DIFF))
        path = f.name
    if git("apply", "--check", "-R", "--binary", path, check=False).returncode == 0:
        print("round154k: already applied")
    else:
        r = git("apply", "--3way", "--binary", path, check=False)
        if r.returncode != 0:
            git("checkout", "--", "map/app.js", "map/test.mjs", check=False)
            sys.exit("round154k: the diff did not apply:\n" + r.stdout + r.stderr)
        print("round154k: applied")
    text = h.read_text(encoding="utf-8")
    add = "".join(n if n.endswith("\n\n") else n.rstrip("\n") + "\n\n" for n in NOTES if n.split("\n", 1)[0] not in text)
    if add:
        at = text.index("\n## Round ") + 1
        h.write_text(text[:at] + add + text[at:], encoding="utf-8")


DIFF = ''

if __name__ == "__main__":
    main()
